package com.mannvaasam.controller; import com.mannvaasam.service.DeliveryService;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/delivery") public class DeliveryController{final DeliveryService s;DeliveryController(DeliveryService s){this.s=s;}@GetMapping("/distance") Map<String,Object> distance(@RequestParam double sellerLat,@RequestParam double sellerLon,@RequestParam double buyerLat,@RequestParam double buyerLon,@RequestParam double radiusKm){double d=s.distanceKm(sellerLat,sellerLon,buyerLat,buyerLon);return Map.of("distanceKm",d,"deliverable",d<=radiusKm);}}